def transform(grid):
    import random

    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    palette = list(counts)
    weights = [counts[v] for v in palette]
    rng = random.Random(str(grid))

    out = [list(row) + [rng.choices(palette, weights=weights)[0]
                        for _ in range(w)] for row in grid]
    for _ in range(h):
        out.append([rng.choices(palette, weights=weights)[0]
                    for _ in range(2 * w)])
    return out
